async function saveContent(){const button=document.querySelector('[data-action="save-content"]');button.disabled=true;try{if(activeTab==='nations'){const cards=[...document.querySelectorAll('.nation-admin-card')];for(const card of cards){const item=content.nations.find(n=>(n.id?`nation-${n.id}`:`nation-${n.draftKey}`)===card.dataset.key);if(!item)continue;const payload={name:card.querySelector('[name="nation-name"]').value,owner:card.querySelector('[name="nation-owner"]').value,description:card.querySelector('[name="nation-description"]').value,rules:card.querySelector('[name="nation-rules"]').value,images:item.images||[]};if(item.id)await api('/api/admin/nations/'+encodeURIComponent(item.id),{method:'PUT',body:JSON.stringify(payload)});else{const saved=await api('/api/admin/nations',{method:'POST',body:JSON.stringify(payload)});item.id=saved.id;}}await loadContent();toast('Cards das nações salvos no banco de dados.');return;}const next=collectContent();if(!content.allowedTabs?.includes('community'))delete next.links;await api('/api/admin/content',{method:'PUT',body:JSON.stringify(next)});await loadContent();toast('Alterações salvas no banco de dados.');}catch(e){toast(e.message,true);button.disabled=false;}}
