function composeLocalNews(category,idea,fileNames=[]){const raw=String(idea||'').trim(),paragraphs=raw.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean),sentences=raw.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean),cleanHead=(paragraphs[0]||raw).replace(/^#{1,6}\s*/,'').replace(/^[-*•]\s*/,''),headline=(cleanHead.split(/[.!?\n]/)[0]||cleanHead).trim().slice(0,115),lead=(sentences[0]||raw).slice(0,420),full=raw.slice(0,12000),subject=headline||'Uma nova etapa no Frontline MC';const modes=[{prefix:category==='Aviso'?'Aviso da comunidade':category==='Anúncio'?'Comunicado oficial':'Notícia em destaque',summary:'Frontline MC: '+lead,heads:['O comunicado','Contexto da notícia','O que a comunidade precisa saber','Acompanhe os próximos passos'],texts:[full,'Esta versão organiza os pontos enviados em uma comunicação direta para a comunidade Frontline MC. O texto-base apresentado pelo autor permanece como fonte das informações deste rascunho.','A publicação destaca o tema descrito no briefing. Confira os detalhes e os nomes citados antes de divulgar para todos os jogadores.','Use esta notícia como registro do anúncio e atualize o rascunho caso novas informações confirmadas sejam necessárias.']},{prefix:'Uma nova etapa',summary:'Uma leitura narrativa para '+lead,heads:['O cenário','A informação central','O impacto para a comunidade','O capítulo seguinte'],texts:['No universo Frontline MC, cada mudança abre novas possibilidades. '+full,'O ponto central desta publicação é: '+lead+' A composição foi organizada para apresentar primeiro a ideia e depois os seus detalhes.','Jogadores podem consultar esta publicação para entender o assunto e acompanhar as informações reunidas pelo autor. Nenhum detalhe adicional foi inventado pelo gerador local.','Este rascunho pode ser complementado no painel antes da publicação. As imagens escolhidas aparecem junto ao texto, mantendo o arquivo original.']},{prefix:'Entenda o que muda',summary:'Os principais detalhes de '+lead,heads:['Em poucas palavras','Pontos principais','O que isso representa','Informações e continuidade'],texts:['Esta notícia reúne o briefing enviado pelo responsável: '+full,'A mensagem principal pode ser resumida assim: '+lead+' A organização desta versão prioriza a leitura dos fatos e do contexto que foi fornecido.','O texto não acrescenta nomes, datas ou promessas que não estejam no briefing. Revise os pontos específicos e ajuste o que quiser no editor da notícia.','As imagens foram guardadas no servidor e serão organizadas na notícia pela ordem escolhida, com a imagem principal em primeiro lugar.']}];return modes.map((mode,index)=>({number:index+1,title:(mode.prefix+': '+subject).slice(0,180),summary:mode.summary.slice(0,1000),sections:mode.heads.map((heading,part)=>({heading,text:mode.texts[part]}))}));}
