root.addEventListener('submit',async event=>{const form=event.target;if(form.id==='news-ai-choice'){event.preventDefault();const choiceText=String(new FormData(form).get('choice')||'').trim(),choice=/^[1-3]$/.test(choiceText)?choiceText:'';if(choice)chooseNewsAiDraft(Number(choice)-1);else{newsAiSession.messages.push({role:'assistant',text:'Este assistente só ajuda a criar notícias, avisos e anúncios do Frontline MC.'});renderPanel();}return;}if(form.id!=='news-ai-brief')return;event.preventDefault();const session=newsAiSession;if(!session||!session.files.length)return;session.category=new FormData(form).get('category');session.idea=new FormData(form).get('idea').trim();if(session.idea.length<12){toast('Descreva a notícia com pelo menos 12 caracteres.',true);return;}if(session.idea.split(/\s+/).filter(Boolean).length>2000){toast('O texto-base pode ter até 2.000 palavras.',true);return;}session.files.forEach((image,index)=>image.primary=index===session.primary);session.messages.push({role:'user',text:`${session.category} · ${session.files.length} ${session.files.length===1?'imagem':'imagens'} · ${session.idea}`});session.step='generating';void saveNewsSession();renderPanel();try{session.uploaded=[];session.outputFiles=[...session.files].sort((a,b)=>Number(b.primary)-Number(a.primary));for(const image of session.outputFiles){const response=await fetch('/api/admin/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','x-csrf-token':csrfToken},body:await image.file.arrayBuffer()}),result=await parseApiResponse(response);if(!response.ok)throw new Error(result.error||'Não consegui enviar uma imagem.');session.uploaded.push({url:result.url,ratio:image.ratio,primary:image.primary});}const generatedResponse=await fetch('/api/admin/news/generate',{method:'POST',headers:{'Content-Type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify({category:session.category,mode:'organize',idea:session.idea,images:session.uploaded})}),generated=await parseApiResponse(generatedResponse);if(!generatedResponse.ok)throw new Error(generated.error||'Não foi possível gerar o rascunho.');session.variants=generated.options;session.model=generated.model;session.step='choices';session.messages.push({role:'assistant',text:'Preparei um rascunho completo. Confira a prévia e use o botão para abrir no editor.'});void saveNewsSession();renderPanel();root.querySelector('.news-ai-options')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){session.step='brief';session.messages.push({role:'assistant',text:error.message});void saveNewsSession();renderPanel();toast(error.message,true);}});
function syncNewsCanvas(card){if(!card)return;const i=Number(card.dataset.newsIndex),item=content.news[i];if(!item)return;item.title=card.querySelector(`[name="news-title-${i}"]`)?.value||'';item.category=card.querySelector(`[name="news-category-${i}"]`)?.value||'Notícia';item.body=card.querySelector(`[name="news-body-${i}"]`)?.value||'';item.published=Boolean(card.querySelector(`[name="news-published-${i}"]`)?.checked);item.layout=[...card.querySelectorAll('.news-layout-block')].map(el=>{const old=item.layout?.find(b=>b.id===el.dataset.blockId)||{};const cs=el.style;const text=el.querySelector('[data-layout-text]');return {...old,id:el.dataset.blockId,type:el.classList.contains('image-block')?'image':'text',text:text?.value??old.text??'',x:parseFloat(cs.left)||0,y:parseFloat(cs.top)||0,w:parseFloat(cs.width)||40,h:parseFloat(cs.height)||200,fontSize:Number(el.querySelector('[data-layout-size]')?.value||old.fontSize||22),align:cs.textAlign||old.align||'left',bold:cs.fontWeight==='700'||old.bold,italic:cs.fontStyle==='italic'||old.italic};});}
function richNewsText(value=""){return String(value||"").split('\n').map(line=>{if(!line.trim())return "<br>";const h=line.match(/^(#{1,3})\s+(.+)$/),safe=escape(h?h[2]:line).replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/~~(.+?)~~/g,"<del>$1</del>").replace(/`([^`]+)`/g,"<code>$1</code>");return h?`<span class="news-md-heading news-md-h${h[1].length}">${safe}</span>`:safe;}).join("<br>");}
function articleLayoutMarkup(item){const layout=Array.isArray(item.layout)?[...item.layout].sort((a,b)=>(Number(a.y)||0)-(Number(b.y)||0)||(Number(a.x)||0)-(Number(b.x)||0)):[],height=Math.max(340,...layout.map(b=>(Number(b.y)||0)+(Number(b.h)||180)+44)),blocks=layout.map(b=>b.type==='image'?`<figure class="member-preview-image ${b.animation==='float'?'image-float':b.animation==='drift'?'image-drift':''}" style="left:${Number(b.x)||0}%;top:${Number(b.y)||0}px;width:${Math.max(4,Math.min(100,Number(b.w)||40))}%;height:${Math.max(40,Number(b.h)||180)}px;--member-ratio:${b.ratio>0?1/b.ratio:1.78};z-index:${b.layer==='front'?3:1}"><img src="${escape(b.url||'')}" alt="Imagem da notícia"></figure>`:`<div class="member-preview-text" style="left:${Number(b.x)||0}%;top:${Number(b.y)||0}px;width:${Math.max(4,Math.min(100,Number(b.w)||40))}%;min-height:${Math.max(40,Number(b.h)||180)}px;z-index:2;--member-font:${Math.max(14,Math.min(300,Number(b.fontSize)||22))}px;text-align:${['left','center','right'].includes(b.align)?b.align:'left'};font-weight:${b.bold?'700':'400'};font-style:${b.italic?'italic':'normal'}">${richNewsText(b.text||'')}</div>`).join(''),date=new Date(item.createdAt||Date.now()),dateLabel=Number.isNaN(date.getTime())?'':date.toLocaleString('pt-BR',{dateStyle:'long',timeStyle:'short'}),author=item.authorName||item.author_name||'Equipe Frontline',role=item.authorRole||item.author_role||'Comunidade';return `<div class="member-preview-shell"><div class="member-preview-ribbon"><span>PRÉVIA DO MEMBRO</span><span>Assim a notícia aparecerá no site</span></div><article class="member-preview-page"><header class="member-preview-heading"><div class="member-preview-author"><span>${escape((author[0]||'F').toUpperCase())}</span><div><strong>${escape(author)}</strong><small>${escape(role)}</small></div></div><small class="member-preview-category">${escape(item.category||'NOTÍCIA')}</small><h2>${escape(item.title||'Título da notícia')}</h2>${item.body?`<p>${richNewsText(item.body)}</p>`:''}</header><section class="member-preview-content"><div class="member-preview-canvas" style="min-height:${height}px">${blocks}</div><footer><time>${escape(dateLabel)}</time></footer></section></article></div>`;}
function arrangeNewsText(layout){const images=layout.filter(b=>b.type==='image');const texts=layout.filter(b=>b.type==='text'&&String(b.text||'').trim()).sort((a,b)=>(Number(a.y)||0)-(Number(b.y)||0));for(const text of texts){let guard=0,changed=true;while(changed&&guard++<images.length+2){changed=false;const tx=Number(text.x)||0,tw=Number(text.w)||40,ty=Number(text.y)||0,th=Number(text.h)||180;for(const image of images){const ix=Number(image.x)||0,iw=Number(image.w)||40,iy=Number(image.y)||0,ih=Number(image.h)||180;const overlaps=tx<ix+iw&&tx+tw>ix&&ty<iy+ih+16&&ty+th>iy-16;if(overlaps){text.y=iy+ih+28;changed=true;break;}}}}return layout;}
function syncAutoLayoutToCanvas(card,item){const canvas=card.querySelector('.news-canvas');for(const block of item.layout){const el=card.querySelector(`[data-block-id="${CSS.escape(block.id)}"]`);if(el)el.style.top=`${Number(block.y)||0}px`;}if(canvas)canvas.style.height=`${Math.max(620,...item.layout.map(b=>(Number(b.y)||0)+(Number(b.h)||200)+50))}px`;}
