root.addEventListener('click',event=>{const toggle=event.target.closest('[data-image-menu-toggle]');if(toggle){const menu=toggle.closest('.image-option-menu');root.querySelectorAll('.image-option-menu.open').forEach(open=>{if(open!==menu){open.classList.remove('open');open.querySelector('[data-image-menu-toggle]')?.setAttribute('aria-expanded','false');}});menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(menu.classList.contains('open')));return;}if(!event.target.closest('.image-option-menu'))root.querySelectorAll('.image-option-menu.open').forEach(open=>open.classList.remove('open'));const choice=event.target.closest('[data-image-option]');if(!choice)return;const card=choice.closest('.news-composer'),item=card&&content.news[Number(card.dataset.newsIndex)];if(!item)return;syncNewsCanvas(card);const [indexText,property,value]=choice.dataset.imageOption.split(':'),block=item.layout[Number(indexText)];if(!block)return;block[property]=value;const el=card.querySelector('[data-block-id="'+CSS.escape(block.id)+'"]');if(el){if(property==='layer')el.style.zIndex=value==='front'?'3':'1';if(property==='animation'){const image=el.querySelector('img');if(image)image.dataset.motion=value;}}const menu=choice.closest('.image-option-menu');menu.querySelector('[data-image-menu-toggle] span').textContent=choice.querySelector('span').textContent;menu.querySelectorAll('[data-image-option]').forEach(option=>{const selected=option===choice;option.setAttribute('aria-selected',String(selected));option.querySelector('i').textContent=selected?'✓':'';});menu.classList.remove('open');menu.querySelector('[data-image-menu-toggle]').setAttribute('aria-expanded','false');previewed.delete(card.dataset.key);const save=card.querySelector('[data-action="save-news"]');if(save)save.disabled=true;});
