root.addEventListener('pointerdown',e=>{const grip=e.target.closest('[data-layout-drag],[data-layout-resize]');if(!grip)return;const block=grip.closest('.news-layout-block'),canvas=block?.parentElement;if(!block||!canvas)return;e.preventDefault();const img=block.querySelector('img');layoutPointer={block,canvas,resize:grip.hasAttribute('data-layout-resize'),image:block.classList.contains('image-block'),ratio:img?.naturalWidth&&img?.naturalHeight?img.naturalHeight/img.naturalWidth:((parseFloat(block.style.height)||200)/Math.max(1,(parseFloat(block.style.width)||40)/100*canvas.clientWidth)),direction:grip.dataset.layoutResize||'se',x:e.clientX,y:e.clientY,left:parseFloat(block.style.left)||0,top:parseFloat(block.style.top)||0,width:parseFloat(block.style.width)||40,height:parseFloat(block.style.height)||200,canvasWidth:canvas.clientWidth};grip.setPointerCapture(e.pointerId);});
